{"type":"message_start","message":{"role":"toolResult","toolCallId":"call_29rnf0ue","toolName":"read","content":[{"type":"text","text":"import { defineSeed } from '@nocobase/db';

interface DeviceSeedRow {
  readonly code: string;
  readonly name: string;
  readonly status: 'available' | 'borrowed';
  readonly notes: string;
}

/**
 * Two fictional devices so a fresh installation has something to look at. Names and notes are sample content, not
 * translations: they stay exactly as written whichever language the interface is showing.
 *
 * The seed is idempotent by `code`: a replay creates only what is missing and leaves a device someone has since
 * edited alone.
 */
const DEVICES: readonly DeviceSeedRow[] = [
  {
    code: 'DEV-001',
    name: '会议室投影仪',
    status: 'available',
    notes: '三层 A 会议室，含遥控器和 HDMI 线。',
  },
  {
    code: 'DEV-002',
    name: 'Field Measurement Tablet',
    status: 'borrowed',
    notes: 'With the field team since Monday; due back Friday.',
  },
];

const seed = defineSeed({
  name: '202610070002_sample_devices',
  sample: true,
  transaction: true,

  async run({ repository }) {
    const devices = repository('devices');
    const now = new Date();

    for (const device of DEVICES) {
      const existing = await devices.findOne({
        filter: { code: device.code },
      });
      if (existing) continue;

      await devices.createOne({
        values: {
          code: device.code,
          name: device.name,
          status: device.status,
          notes: device.notes,
          createdAt: now,
          updatedAt: now,
        },
      });
    }
  },
});

export default seed;
